export async function database(){return new Promise((resolve,reject)=>{if(!globalThis.indexedDB){reject(new Error('Browser storage is unavailable.'));return;}const req=indexedDB.open('drews-play-along-assets',1);req.onupgradeneeded=()=>req.result.createObjectStore('audio',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
export async function storeAudio(record){const db=await database();return new Promise((resolve,reject)=>{const tr=db.transaction('audio','readwrite');tr.objectStore('audio').put(record);tr.oncomplete=()=>{db.close();resolve();};tr.onerror=()=>{db.close();reject(tr.error);};});}
export async function readAudio(id){const db=await database();return new Promise((resolve,reject)=>{const tr=db.transaction('audio','readonly'),req=tr.objectStore('audio').get(id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);tr.oncomplete=()=>db.close();});}
export function bytesToBase64(bytes){const a=new Uint8Array(bytes),parts=[];for(let i=0;i<a.length;i+=8192)parts.push(String.fromCharCode(...a.subarray(i,i+8192)));return btoa(parts.join(''));}
export function unpackAudio(packed,max){if(typeof packed?.base64!=='string'||packed.base64.length>Math.ceil(max/3)*4+4)throw new Error('The attached audio is too large or invalid.');const data=atob(packed.base64),bytes=Uint8Array.from(data,c=>c.charCodeAt(0)).buffer;if(bytes.byteLength>max)throw new Error('The attached audio is too large.');return bytes;}
